SELECT COUNT(*) AS count FROM AUD_PIPELINE_REFRESHES t WHERE t.PROJECT_ID=:project_id AND t.REFRESHED_AT<:cutoff
AND t.REFRESH_ID<>(SELECT MAX(latest.REFRESH_ID) FROM AUD_PIPELINE_REFRESHES latest WHERE latest.PIPELINE_ID=t.PIPELINE_ID)
AND (t.STATUS<>'SUCCESS' OR t.REFRESH_ID<>(SELECT MAX(good.REFRESH_ID) FROM AUD_PIPELINE_REFRESHES good WHERE good.PIPELINE_ID=t.PIPELINE_ID AND good.STATUS='SUCCESS'))
AND (SELECT referencing.REFRESH_ID FROM AUD_PIPELINE_REFRESHES referencing WHERE referencing.SNAPSHOT_REFRESH_ID=t.REFRESH_ID LIMIT 1) IS NULL
